const dirt = find_block({ names: ['dirt', 'coarse_dirt', 'grass_block', 'podzol'], max_distance: 16 });
if (!dirt) {
  const here = position();
  await move_to(here.x + 12, here.y, here.z + 12);
  return { done: false, detail: 'no ground here; walking on' };
}
const broke = await dig(dirt.x, dirt.y, dirt.z);
if (!broke.ok) {
  return { done: false, detail: broke.detail };
}
await leave_at_depot();  // the bag, in one standing — walking away between items takes the pile back
return { done: true, detail: 'broke up the ground and left the bag at the depot' };
